    public static IReadOnlyCollection<string> Languages => new[] { "en", "it", "es", "fr" };
    public string CurrentLanguage { get; private set; } = "en";
    public ReadOnlyObservableCollection<string> AvailableLanguages { get; } = new(new ObservableCollection<string>(Languages));
    public event EventHandler? LanguageChanged;

    public void SetLanguage(string language)
    {
        if (!Resources.ContainsKey(language)) throw new ArgumentException("Unsupported language.", nameof(language));
        CurrentLanguage = language;
        LanguageChanged?.Invoke(this, EventArgs.Empty);
    }

    public string Get(string key) => Resources[CurrentLanguage].TryGetValue(key, out var value) ? value : Resources["en"].TryGetValue(key, out var fallback) ? fallback : $"[{key}]";

    public static LocalizationValidation Validate()
    {
        var englishKeys = Resources["en"].Keys.ToHashSet(StringComparer.OrdinalIgnoreCase);
        var missing = Resources.Where(pair => pair.Key != "en").ToDictionary(pair => pair.Key, pair => englishKeys.Except(pair.Value.Keys, StringComparer.OrdinalIgnoreCase).ToArray());
        return new LocalizationValidation(englishKeys.Count, missing);
    }
}

public sealed record LocalizationValidation(int TotalKeys, IReadOnlyDictionary<string, string[]> MissingByLanguage)
{
    public bool IsComplete => MissingByLanguage.Values.All(values => values.Length == 0);
}
